   [87]={next_id=88, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="在你出现之前，我的人生就像一场永远无法醒来的噩梦。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [88]={next_id=89, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="被抛弃的那天，我在家门口坐到深夜，邻居家的灯光一盏盏熄灭，街道越来越黑。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [89]={next_id=90, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我数着经过的马车，数着天上的星星，数着自己的心跳。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [90]={next_id=91, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我在想：是不是我做错了什么？是不是我不够乖？是不是我吃饭时掉了一粒米，睡觉时多说了一句梦话？", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [91]={next_id=92, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="辉月的话像是冷夜中的冰雨，你的眼前不由自主地浮现了一个在黑夜里孤单的小小身影。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [92]={next_id=93, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="后来我不再想了，因为我知道有些问题没有答案，或者说……答案本身毫无意义。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我被教廷收留，获得星源共鸣的力量，成为命星骑士。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
