   [104]={next_id=105, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我开始期待每一次见面，珍惜每一封来信，记住你说过的每一句话。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
