   [116]={next_id=-1, abreast_id={}, pType =4, cg_type =10, dialog=1, msg="null", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [117]={next_id=118, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你没有犹豫，踏上了光之桥。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [118]={next_id=119, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="脚下传来坚实而温暖的触感，仿佛走在铺满阳光的草地上，桥面随着你的步伐微微起伏，如同呼吸。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [119]={next_id=120, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="一步，两步……你走向湖心，走向那个在等待的少女。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [120]={next_id=121, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="走到辉月面前时，她仰起脸看着你，眼眸里倒映着星辉和你的身影，清澈得让人心颤。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [121]={next_id=122, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你轻轻握住她的手，她的手有些凉，但掌心传来细微的颤抖，暴露了她内心的紧张。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [122]={next_id=123, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="最后一段舞……我想和链尉官一起跳。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [123]={next_id=124, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她轻轻拉动你的手，引导着你的步伐，就像下午你引导她时那样。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [124]={next_id=125, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="没有复杂的舞步，没有炫技的旋转，只是最简单的移动，最基础的姿态。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [125]={next_id=126, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但在星辉下，在星月湖的中心，在星源共鸣构筑的光之舞台上，这简单的舞蹈拥有了震撼人心的力量。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
