   [135]={next_id=136, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="辉月先是一僵，随后放松下来，双手环住你的脖子，生涩但真诚地回应。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [136]={next_id=137, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="星源共鸣在这一刻达到顶峰，以你们两人为中心，湖面爆发出耀眼的蓝色光芒。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [137]={next_id=138, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那些光芒冲天而起，在夜空中交织、盘旋，最后化作无数光点洒落，如同降下一场温柔的星雨。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
