   [146]={next_id=147, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="其实我一直很害怕……", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [147]={next_id=148, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="害怕自己太贪心，明明已经拥有了教廷的大家，拥有了命星骑士的身份，拥有了守护维拉提亚的意义。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [148]={next_id=149, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="却还想要更多……想要你的关注，你的温柔，你的……爱。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [149]={next_id=150, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但今天晚上，在跳舞的时候，我突然明白了。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [150]={next_id=151, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="辉月转头看向你，水珠在其发梢间滑落。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [151]={next_id=152, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="爱不是有限资源，不会因为分给了我就变少。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [152]={next_id=153, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而我也不是那个七岁的小女孩了，我不再是被动等待别人给予的孤儿。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [153]={next_id=154, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我可以去爱，可以去付出，可以去争取属于自己的幸福。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [154]={next_id=155, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这都是链尉官教会我的。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [155]={next_id=156, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你伸手将她拥入怀中，辉月侧脸紧贴着你的胸口，安心地感受着你的心跳。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [156]={next_id=157, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="有时候我会想，如果小时候没有经历那些事情，我会是什么样子？", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [157]={next_id=158, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可能是个普通的女孩，会上学，会交朋友，会在合适的年龄谈一场普通的恋爱。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [158]={next_id=159, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但那样的话……我就不会成为命星骑士，不会来到维拉提亚，不会遇见链尉官。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [159]={next_id=160, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="辉月轻轻擦去眼角的泪珠，瞳孔中你的倒影愈发明亮。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [160]={next_id=161, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="所以现在我觉得，也许一切都是最好的安排。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [161]={next_id=162, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那些伤痛没有消失，它们永远是我的一部分。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [162]={next_id=163, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="但它们不再定义我。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [163]={next_id=164, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我不再是“那个被抛弃的女孩”，而是……“爱着链尉官的辉月”。", msg_color="", msg_size=0, talker="辉月", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4518", 0, 0, 12, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [164]={next_id=165, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她说这话时，眼睛一直看着你。那种专注的、毫无保留的目光，让你的心脏重重跳了一下。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [165]={next_id=166, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="某种强烈的冲动涌上来——想要再次吻她，想要把她紧紧抱在怀里，想要确认这一切不是月光下的美梦。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [166]={next_id=167, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="辉月身体却突然一软，整个人靠进了你的怀里。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_15_104.jpg", video_url="", music_id="-2", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=1, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
